using Microsoft.Data.Sqlite;
using System.Text.Json;
using MediLabX.Native.Models;
namespace MediLabX.Native.Services;
public sealed class Store {
 public static string Root=>Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),"MediLab","Standard","NativeWpf");
 public string FileName=>Path.Combine(Root,"medilab-native.sqlite");
 private static readonly JsonSerializerOptions J=new(){PropertyNameCaseInsensitive=true,WriteIndented=false};
 public Store(){Directory.CreateDirectory(Root);using var c=Connect();using var cmd=c.CreateCommand();cmd.CommandText="CREATE TABLE IF NOT EXISTS records (bucket TEXT NOT NULL,id TEXT NOT NULL,json TEXT NOT NULL,updated TEXT NOT NULL,PRIMARY KEY(bucket,id)); CREATE INDEX IF NOT EXISTS idx_records_bucket ON records(bucket);";cmd.ExecuteNonQuery();SeedTests();}
 private SqliteConnection Connect(){var c=new SqliteConnection(new SqliteConnectionStringBuilder{DataSource=FileName,Mode=SqliteOpenMode.ReadWriteCreate,Cache=SqliteCacheMode.Shared}.ToString());c.Open();using var p=c.CreateCommand();p.CommandText="PRAGMA busy_timeout=5000; PRAGMA journal_mode=WAL; PRAGMA foreign_keys=ON;";p.ExecuteNonQuery();return c;}
 public List<T> All<T>(string bucket){using var c=Connect();using var cmd=c.CreateCommand();cmd.CommandText="SELECT json FROM records WHERE bucket=$b ORDER BY updated DESC";cmd.Parameters.AddWithValue("$b",bucket);using var r=cmd.ExecuteReader();var a=new List<T>();while(r.Read()){try{var v=JsonSerializer.Deserialize<T>(r.GetString(0),J);if(v is not null)a.Add(v);}catch(JsonException){}}return a;}
 public T? One<T>(string bucket,string id){using var c=Connect();using var cmd=c.CreateCommand();cmd.CommandText="SELECT json FROM records WHERE bucket=$b AND id=$i";cmd.Parameters.AddWithValue("$b",bucket);cmd.Parameters.AddWithValue("$i",id);var raw=cmd.ExecuteScalar() as string;return raw is null?default:JsonSerializer.Deserialize<T>(raw,J);}
 public void Put<T>(string bucket,string id,T value){using var c=Connect();using var cmd=c.CreateCommand();cmd.CommandText="INSERT INTO records(bucket,id,json,updated) VALUES($b,$i,$v,$u) ON CONFLICT(bucket,id) DO UPDATE SET json=excluded.json,updated=excluded.updated";cmd.Parameters.AddWithValue("$b",bucket);cmd.Parameters.AddWithValue("$i",id);cmd.Parameters.AddWithValue("$v",JsonSerializer.Serialize(value,J));cmd.Parameters.AddWithValue("$u",DateTime.UtcNow.ToString("O"));cmd.ExecuteNonQuery();}
 public void Delete(string bucket,string id){using var c=Connect();using var cmd=c.CreateCommand();cmd.CommandText="DELETE FROM records WHERE bucket=$b AND id=$i";cmd.Parameters.AddWithValue("$b",bucket);cmd.Parameters.AddWithValue("$i",id);cmd.ExecuteNonQuery();}
 public string NextReceipt(){using var c=Connect();using var tx=c.BeginTransaction();using var get=c.CreateCommand();get.Transaction=tx;get.CommandText="SELECT json FROM records WHERE bucket='meta' AND id='receipt'";var raw=get.ExecuteScalar() as string;var n=raw is null?1001:int.TryParse(raw,out var v)?v:1001;using var save=c.CreateCommand();save.Transaction=tx;save.CommandText="INSERT INTO records(bucket,id,json,updated) VALUES('meta','receipt',$n,$u) ON CONFLICT(bucket,id) DO UPDATE SET json=excluded.json,updated=excluded.updated";save.Parameters.AddWithValue("$n",(n+1).ToString());save.Parameters.AddWithValue("$u",DateTime.UtcNow.ToString("O"));save.ExecuteNonQuery();tx.Commit();return "AH-"+n;}
 public CentreSettings Settings{get=>One<CentreSettings>("settings","centre")??new();set=>Put("settings","centre",value);}
 public void Backup(string selectedPath){Directory.CreateDirectory(Path.GetDirectoryName(selectedPath)!);using var c=Connect();using var from=new SqliteConnection($"Data Source={FileName};Mode=ReadOnly");from.Open();using var to=new SqliteConnection($"Data Source={selectedPath}");to.Open();from.BackupDatabase(to);}
 private void SeedTests(){if(All<TestDefinition>("tests").Count!=0)return;var path=Path.Combine(AppContext.BaseDirectory,"Assets","imported-tests.json");if(!File.Exists(path))return;using var root=JsonDocument.Parse(File.ReadAllText(path));foreach(var v in root.RootElement.EnumerateArray()){var id=v.TryGetProperty("id",out var idp)?idp.ToString():Guid.NewGuid().ToString("N");decimal price=0;if(v.TryGetProperty("price",out var pp)&&pp.ValueKind==JsonValueKind.Number)pp.TryGetDecimal(out price);var t=new TestDefinition{Id=id,Name=v.TryGetProperty("name",out var np)?np.GetString()??"":"",Abbr=v.TryGetProperty("abbr",out var ab)?ab.GetString()??"":"",Department="Radiology",Price=price};Put("tests",t.Id,t);}}
}